/// Helper: Extract metric value from text like "Average PSNR: 25.46 dB"
fn extract_metric(text: &str, label: &str) -> Option<f32> {
    text.lines()
        .find(|line| line.contains(label))
        .and_then(|line| {
            line.split(':')
                .nth(1)
                .and_then(|value_str| {
                    value_str
                        .split_whitespace()
                        .next()
                        .and_then(|num_str| num_str.parse::<f32>().ok())
                })
        })
}

