    gt_tensor = torch.from_numpy(gt * 2.0 - 1.0).permute(2, 0, 1).unsqueeze(0)
    render_tensor = torch.from_numpy(render * 2.0 - 1.0).permute(2, 0, 1).unsqueeze(0)

    loss_fn = lpips.LPIPS(net='alex', verbose=False)
